def search():
        q = request.args.get("q", "")
        rows = db().execute("SELECT title FROM notes WHERE title LIKE ?", (f"%{q}%",)).fetchall()
        return render_template_string("<h1>Results for {{ q }}</h1>{% for r in rows %}<li>{{ r[0] }}</li>{% endfor %}",
                                      q=q, rows=rows)
